package app.kivo.store;
import android.app.*;import android.content.*;import android.database.Cursor;import android.os.*;import android.net.Uri;import org.json.*;import java.io.*;import java.util.*;
/** Transfers are owned by Android's DownloadManager, not by the Activity. */
final class Downloads {
 final MainActivity host;final DownloadManager manager;final android.content.SharedPreferences prefs;
 Downloads(MainActivity h){host=h;prefs=h.prefs;manager=(DownloadManager)h.getSystemService(Context.DOWNLOAD_SERVICE);}
 synchronized JSONArray records(){try{return new JSONArray(prefs.getString("systemDownloads","[]"));}catch(Exception e){return new JSONArray();}}
 synchronized void save(JSONArray records){prefs.edit().putString("systemDownloads",records.toString()).apply();}
 void enqueue(String raw,long assetId)throws Exception{
 String repo=MainActivity.repo(raw);if(repo.startsWith("fdroid/")){enqueueFdroid(repo,assetId);return;}if(host.blocked(repo))throw new IOException("Aplicación bloqueada.");JSONObject release=host.catalog.get(repo),asset=host.get("repos/"+repo+"/releases/assets/"+assetId);if(release==null||asset.optLong("id")!=assetId)throw new IOException("Vuelve a abrir la ficha.");JSONObject updatedEntry=new JSONObject(release.toString());JSONArray copies=new JSONArray(),listed=updatedEntry.optJSONArray("assets");boolean found=false;if(listed!=null)for(int i=0;i<listed.length();i++){JSONObject one=listed.getJSONObject(i);if(one.optLong("id")==assetId){one=new JSONObject(one.toString()).put("name",asset.getString("name")).put("size",asset.getLong("size")).put("url",asset.getString("browser_download_url")).put("digest",asset.optString("digest"));found=true;}copies.put(one);}if(!found)throw new IOException("La variante cambió. Vuelve a comprobar la ficha.");updatedEntry.put("assets",copies);host.catalog.put(repo,updatedEntry);if(!host.inspector.mayDownload(repo,assetId))return;
 if(asset==null)throw new IOException("La versión cambió. Comprueba la ficha de nuevo.");String url=asset.getString("browser_download_url"),name=asset.getString("name");long size=asset.optLong("size");if(!url.startsWith("https://github.com/"+repo+"/releases/download/")||!name.toLowerCase(Locale.ROOT).endsWith(".apk")||size<1||size>500L*1024*1024)throw new IOException("APK u origen no válido.");
 JSONArray all=records();for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i);if(r.optString("repo").equalsIgnoreCase(repo)&&r.optLong("assetId")==assetId){JSONObject current=state(r);if(!Arrays.asList("failed","cancelled").contains(current.optString("state"))){host.status("Esta descarga ya está en tu lista.");publish();return;}}}
 String destination=UUID.randomUUID().toString()+".apk";DownloadManager.Request request=new DownloadManager.Request(Uri.parse(url)).setTitle(repo.split("/")[1]).setDescription("APK del creador · Kivo Store").setMimeType("application/vnd.android.package-archive").setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE).setDestinationInExternalFilesDir(host,Environment.DIRECTORY_DOWNLOADS,destination).setAllowedOverRoaming(false);
 if(prefs.getBoolean("wifiOnly",false))request.setAllowedNetworkTypes(DownloadManager.Request.NETWORK_WIFI);long id=manager.enqueue(request);JSONObject record=new JSONObject();record.put("id",id);record.put("repo",repo);record.put("assetId",assetId);record.put("name",name);record.put("size",size);record.put("digest",asset.optString("digest"));record.put("version",release.optString("tag_name"));record.put("expectedPackage",host.inspector.packageFor(host.catalog.get(repo),assetId));record.put("created",System.currentTimeMillis());all.put(record);save(all);host.status("Descarga añadida. Android la continuará aunque salgas de Kivo.");publish();
 }
 void enqueueFdroid(String repo,long assetId)throws Exception{
 JSONObject app=host.fdroid.find(repo),asset=null;JSONArray assets=app.getJSONArray("assets");for(int i=0;i<assets.length();i++)if(assets.getJSONObject(i).optLong("id")==assetId)asset=assets.getJSONObject(i);
 if(asset==null)throw new IOException("El índice cambió. Abre la ficha de nuevo.");String url=asset.getString("url"),name=asset.getString("name");String path=url.replace("https://f-droid.org/repo","");if(!url.startsWith("https://f-droid.org/repo/")||!Fdroid.safePath(path)||!name.endsWith(".apk")||!asset.optString("digest").matches("sha256:[a-f0-9]{64}"))throw new IOException("Origen F-Droid no válido.");
 JSONArray all=records();for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i);if(r.optString("repo").equals(repo)&&r.optLong("assetId")==assetId&&!Arrays.asList("failed","cancelled").contains(state(r).optString("state"))){host.status("Esta descarga ya está en tu lista.");publish();return;}}
 DownloadManager.Request request=new DownloadManager.Request(Uri.parse(url)).setTitle(app.optString("name")).setDescription("F-Droid · Kivo Store").setMimeType("application/vnd.android.package-archive").setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE).setDestinationInExternalFilesDir(host,Environment.DIRECTORY_DOWNLOADS,UUID.randomUUID().toString()+".apk").setAllowedOverRoaming(false);if(prefs.getBoolean("wifiOnly",false))request.setAllowedNetworkTypes(DownloadManager.Request.NETWORK_WIFI);
 JSONArray signers=asset.getJSONArray("signers");List<String> pins=new ArrayList<>();for(int i=0;i<signers.length();i++){String pin=signers.getString(i);if(!pin.matches("[a-f0-9]{64}"))throw new IOException("Firma esperada no válida.");pins.add(pin);}if(pins.isEmpty())throw new IOException("Falta la firma esperada.");Collections.sort(pins);
 JSONObject rec=new JSONObject();rec.put("repo",repo);rec.put("source","fdroid");rec.put("package",app.getString("package"));rec.put("expectedSigners",String.join(",",pins));rec.put("assetId",assetId);rec.put("name",name);rec.put("size",asset.getLong("size"));rec.put("digest",asset.getString("digest"));rec.put("version",app.optString("version"));rec.put("created",System.currentTimeMillis());rec.put("id",manager.enqueue(request));all.put(rec);save(all);host.status("Descarga F-Droid añadida.");publish();
 }
 synchronized void verified(long id,String pkg,long versionCode,String signers)throws Exception{JSONArray all=records();for(int i=0;i<all.length();i++){JSONObject record=all.getJSONObject(i);if(record.optLong("id")==id){record.put("apkPackage",pkg).put("apkCode",versionCode).put("apkSigners",signers);save(all);return;}}throw new IOException("Descarga no encontrada.");}
 void installationState(JSONObject record,JSONObject out){try{String pkg=record.optString("apkPackage"),sign=record.optString("apkSigners");long code=record.optLong("apkCode");
  // Upgrade old records only when the saved verified APK has the same repo, asset name and release.
  if(pkg.isEmpty()){JSONArray tracks=new JSONArray(prefs.getString("tracked","[]"));for(int i=0;i<tracks.length();i++){JSONObject t=tracks.optJSONObject(i);if(t!=null&&t.optString("repo").equals(record.optString("repo"))&&DownloadInstallPolicy.legacyMatches(record.optString("digest"),t.optString("file"),record.optString("name"),t.optString("assetName"),record.optString("version"),t.optString("downloadedVersion"))){pkg=t.optString("package");code=t.optLong("downloadedCode");sign=prefs.getString("sign:"+t.optString("repo"),"");break;}}}
  if(!InstalledApps.validPackage(pkg)||code<=0||sign.isEmpty())return;int flags=Build.VERSION.SDK_INT>=28?android.content.pm.PackageManager.GET_SIGNING_CERTIFICATES:android.content.pm.PackageManager.GET_SIGNATURES;android.content.pm.PackageInfo info=host.getPackageManager().getPackageInfo(pkg,flags);boolean installed=DownloadInstallPolicy.installed(code,MainActivity.code(info),sign,host.signers(info));out.put("installed",installed);if(installed){out.put("installedPackage",pkg).put("installedVersion",info.versionName==null?"":info.versionName).put("newerInstalled",MainActivity.code(info)>code);}
 }catch(Exception ignored){}}
 JSONObject state(JSONObject r)throws Exception{JSONObject out=new JSONObject(r.toString());out.put("installed",false);installationState(r,out);if(r.optBoolean("cancelled")){out.put("state","cancelled");return out;}try(Cursor c=manager.query(new DownloadManager.Query().setFilterById(r.getLong("id")))){if(c==null||!c.moveToFirst()){out.put("state","failed");out.put("error","El archivo ya no está disponible.");return out;}int status=c.getInt(c.getColumnIndexOrThrow(DownloadManager.COLUMN_STATUS));out.put("bytes",c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_BYTES_DOWNLOADED_SO_FAR)));out.put("total",c.getLong(c.getColumnIndexOrThrow(DownloadManager.COLUMN_TOTAL_SIZE_BYTES)));out.put("state",status==DownloadManager.STATUS_SUCCESSFUL?"ready":status==DownloadManager.STATUS_FAILED?"failed":status==DownloadManager.STATUS_PAUSED?"waiting":status==DownloadManager.STATUS_RUNNING?"downloading":"queued");if(status==DownloadManager.STATUS_PAUSED)out.put("error","Android reanudará la descarga cuando la red lo permita.");if(status==DownloadManager.STATUS_FAILED)out.put("error","La descarga falló. Puedes volver a intentarlo.");}return out;}
 synchronized void publish(){JSONArray out=new JSONArray(),all=records();for(int i=0;i<all.length();i++)try{out.put(state(all.getJSONObject(i)));}catch(Exception ignored){}host.send("downloads",out);host.send("settings",settings());}
 JSONObject settings(){JSONObject o=new JSONObject();try{o.put("wifiOnly",prefs.getBoolean("wifiOnly",false));}catch(Exception ignored){}return o;}
 synchronized void cancel(long id){JSONArray all=records();for(int i=0;i<all.length();i++)try{JSONObject r=all.getJSONObject(i);if(r.optLong("id")==id){manager.remove(id);r.put("cancelled",true);}}catch(Exception ignored){}save(all);publish();}
 void retry(long id)throws Exception{JSONArray all=records();JSONObject chosen=null;for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optLong("id")==id){chosen=all.getJSONObject(i);chosen.put("cancelled",true);manager.remove(id);}save(all);if(chosen!=null)enqueue(chosen.getString("repo"),chosen.getLong("assetId"));}
 synchronized JSONObject find(long id)throws Exception{JSONArray a=records();for(int i=0;i<a.length();i++)if(a.getJSONObject(i).optLong("id")==id)return a.getJSONObject(i);throw new IOException("Descarga no encontrada.");}
 synchronized long clearCompleted(){long freed=0;JSONArray a=records(),keep=new JSONArray();for(int i=0;i<a.length();i++)try{JSONObject rec=a.getJSONObject(i);String s=state(rec).optString("state");if(Arrays.asList("ready","failed","cancelled").contains(s)){long bytes=state(rec).optLong("bytes");if(manager.remove(rec.getLong("id"))>0)freed+=Math.max(0,bytes);}else keep.put(rec);}catch(Exception ignored){}save(keep);publish();return freed;}
}
